//go:build windows

package app

import (
	"bytes"
	"context"
	"embed"
	"encoding/json"
	"errors"
	"io/fs"
	"net/http"
	"os"
	"path/filepath"
	"sync"
	"time"

	"github.com/wailsapp/wails/v2"
	"github.com/wailsapp/wails/v2/pkg/logger"
	"github.com/wailsapp/wails/v2/pkg/options"
	"github.com/wailsapp/wails/v2/pkg/options/assetserver"
	wwindows "github.com/wailsapp/wails/v2/pkg/options/windows"
	wruntime "github.com/wailsapp/wails/v2/pkg/runtime"

	"sound-snoofer/snoofer"
)

// web/dist holds the bundle and stylesheet generated by `npm run build:gui`; all: keeps the
// tracked .gitkeep so Go tests compile before assets are generated.
//
//go:embed web/index.html all:web/dist
var desktopAssets embed.FS

// Desktop exposes only immutable state and the existing semantic action pipe.
type Desktop struct {
	mu               sync.Mutex
	state            ViewState
	version          uint64
	artwork          map[string]string
	artworkVersion   uint64
	animationVersion uint64
	animations       map[string][]snoofer.ArtworkFrame // Replaced wholesale, like state.
	actions          chan UIAction
	ctx              context.Context
}

func (d *Desktop) State(sinceVersion uint64) *ViewUpdate {
	d.mu.Lock()
	defer d.mu.Unlock()
	if d.version == 0 || sinceVersion == d.version {
		return nil
	}
	update := &ViewUpdate{Version: d.version, State: d.state, AnimationVersion: d.animationVersion}
	if sinceVersion == 0 || sinceVersion < d.artworkVersion || sinceVersion > d.version {
		artwork := d.artwork
		update.Artwork = &artwork
	}
	return update // Replaced wholesale; snapshots are never mutated.
}

func (d *Desktop) applyFrame(f frame) {
	d.mu.Lock()
	defer d.mu.Unlock()
	if f.State != nil {
		if f.Version == 0 {
			// The isolated native smoke still supplies complete, unversioned states.
			state, artwork, _ := separateArtwork(*f.State)
			f.State, f.Artwork, f.Version = &state, &artwork, d.version+1
		}
		d.state, d.version = *f.State, f.Version
	}
	if f.Artwork != nil {
		d.artwork, d.artworkVersion = *f.Artwork, d.version
	}
	if f.Animations != nil {
		d.animations, d.animationVersion = *f.Animations, d.version
	}
}

// Animation returns a control's artwork frames, or none. The GUI requests
// them when artwork changes; they are not part of polled state.
func (d *Desktop) Animation(id string) []snoofer.ArtworkFrame {
	d.mu.Lock()
	defer d.mu.Unlock()
	return d.animations[id]
}
func (d *Desktop) Send(action UIAction) error {
	select {
	case <-d.ctx.Done():
		return errors.New("controls disconnected")
	default:
	}
	select {
	case d.actions <- action:
		return nil
	default:
		return errors.New("controls busy; try again")
	}
}

func RunDesktop(ctx context.Context) error {
	assets, err := fs.Sub(desktopAssets, "web")
	if err != nil {
		return err
	}
	exe, err := os.Executable()
	if err != nil {
		return err
	}
	runCtx, cancel := context.WithCancel(ctx)
	defer cancel()
	d := &Desktop{ctx: runCtx, actions: make(chan UIAction, 16)}
	var workers sync.WaitGroup
	err = wails.Run(&options.App{
		Title: "Snoofer", Width: 1280, Height: 820, MinWidth: 800, MinHeight: 600,
		BackgroundColour: options.NewRGB(14, 20, 27),
		AssetServer: &assetserver.Options{Assets: assets, Handler: http.HandlerFunc(func(w http.ResponseWriter, r *http.Request) {
			if r.URL.Path != "/logo.ico" {
				http.NotFound(w, r)
				return
			}
			w.Header().Set("Content-Type", "image/x-icon")
			http.ServeContent(w, r, "logo.ico", time.Time{}, bytes.NewReader(trayIcon))
		})},
		Logger:             logger.NewFileLogger(filepath.Join(filepath.Dir(exe), "snoofer-gui.log")),
		LogLevelProduction: logger.ERROR,
		Windows:            &wwindows.Options{Theme: wwindows.Dark, IsZoomControlEnabled: true, WebviewUserDataPath: filepath.Join(filepath.Dir(exe), "webview-cache")},
		Bind:               []interface{}{d},
		OnDomReady: func(uiCtx context.Context) {
			brandDesktop()
			workers.Add(3)
			go func() {
				defer workers.Done()
				defer cancel()
				decoder := json.NewDecoder(os.Stdin)
				for {
					var f frame
					if err := decoder.Decode(&f); err != nil {
						return
					}
					d.applyFrame(f)
					if f.Focus {
						wruntime.WindowUnminimise(uiCtx)
						wruntime.WindowShow(uiCtx)
					}
				}
			}()
			go func() {
				defer workers.Done()
				encoder := json.NewEncoder(os.Stdout)
				for {
					select {
					case <-runCtx.Done():
						return
					case a := <-d.actions:
						if err := encoder.Encode(a); err != nil {
							cancel()
							return
						}
					}
				}
			}()
			go func() { defer workers.Done(); <-runCtx.Done(); wruntime.Quit(uiCtx) }()
		},
		OnShutdown: func(context.Context) { cancel(); os.Stdin.Close(); os.Stdout.Close() },
	})
	cancel()
	os.Stdin.Close()
	os.Stdout.Close()
	workers.Wait()
	return err
}
